#include <cstddef>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

struct Planet {
    std::string name;
    double radius = 0.0;
    int moons = 0;
};

void printPlanet(const Planet& p) {
    std::cout << p.name << ": radius " << p.radius << " km, moons " << p.moons << '\n';
}

int main() {
    std::cout << std::fixed << std::setprecision(1);
    std::vector<Planet> planets;
    planets.push_back({"Mars", 3389.5, 2});
    planets.push_back({"Jupiter", 69911.0, 95});
    planets.push_back({"Earth", 6371.0, 1});

    std::size_t best = 0;
    for (std::size_t i = 0; i < planets.size(); ++i) {
        printPlanet(planets[i]);
        if (planets[i].moons > planets[best].moons) {
            best = i;
        }
    }
    std::cout << "Most moons: " << planets[best].name << '\n';
    return 0;
}

