example.code:
#include <iomanip>
#include <iostream>

struct Rectangle {
    double width = 0.0;
    double height = 0.0;

    double area() const {
        return width * height;
    }
    double perimeter() const {
        return 2 * (width + height);
    }
    void scale(double factor) {
        width *= factor;
        this->height *= factor;
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    Rectangle r{3.0, 4.0};
    std::cout << r.area() << ' ' << r.perimeter() << '\n';

    r.scale(2.0);
    std::cout << r.width << ' ' << r.height << ' ' << r.area() << '\n';

    Rectangle* p = &r;
    p->scale(1.5);
    std::cout << p->width << ' ' << p->area() << ' ' << r.perimeter() << '\n';
    return 0;
}

