#include <iomanip>
#include <iostream>

struct Circle {
    double radius = 0.0;

    double area() const {
        return 3.14159 * radius * radius;
    }
    double diameter() const {
        return 2 * radius;
    }
    void grow(double amount) {
        radius += amount;
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    Circle c{2.0};
    std::cout << c.area() << ' ' << c.diameter() << '\n';

    c.grow(1.0);
    std::cout << c.radius << ' ' << c.area() << '\n';

    Circle* p = &c;
    p->grow(0.5);
    std::cout << p->radius << ' ' << p->area() << ' ' << c.diameter() << '\n';
    return 0;
}

steps.body:
A struct lets anyone change any field, which is fine for plain data. When the data has a rule to protect (an *invariant*, such as "a balance never goes below zero"), use a `class` and hide the data behind methods.

```cpp
class Counter {
public:
    void add(int n) {
        if (n > 0) {
            count_ += n;   // the method enforces the rule
        }
    }
    int count() const {    // a getter: read-only access
        return count_;
    }

private:
    int count_ = 0;
};
Counter c;
c.add(5);
c.add(-3);                       // refused: not positive
std::cout << c.count() << '\n';  // 5
```

Members under `public:` can be used by any code. Members under `private:` can only be used inside the class's own methods, so `c.count_ = -5;` outside the class does not compile. Every change has to go through a method that checks the rule. The trailing underscore marks private data and frees the plain name for the getter.

`struct` and `class` are the same thing in C++, except for the default: a `struct` starts public and a `class` starts private. This course uses `struct` for plain data and `class` when there are rules to protect.

example.code:
#include <iomanip>
#include <iostream>

class BankAccount {
public:
    void deposit(double amount) {
        if (amount > 0) {
            balance_ += amount;
        }
    }
    bool withdraw(double amount) {
        if (amount <= 0 || amount > balance_) {
            return false;
        }
        balance_ -= amount;
        return true;
    }
    double balance() const {
        return balance_;
    }

private:
    double balance_ = 0.0;
};

int main() {
    std::cout << std::fixed << std::setprecision(2) << std::boolalpha;
    BankAccount account;
    account.deposit(100.0);
    std::cout << "Deposit 100: " << account.balance() << '\n';

    bool ok = account.withdraw(30.0);
    std::cout << "Withdraw 30: " << ok << ' ' << account.balance() << '\n';

    ok = account.withdraw(500.0);
    std::cout << "Withdraw 500: " << ok << ' ' << account.balance() << '\n';

    account.deposit(-20.0);
    std::cout << "Deposit -20: " << account.balance() << '\n';
    return 0;
}

