#include <algorithm>
#include <iostream>

class Thermostat {
public:
    void raise(int amount) {
        target_ = std::clamp(target_ + amount, 10, 30);
    }
    void lower(int amount) {
        target_ = std::clamp(target_ - amount, 10, 30);
    }
    int target() const {
        return target_;
    }

private:
    int target_ = 20;
};

int main() {
    Thermostat t;
    std::cout << "Start: " << t.target() << '\n';
    t.raise(5);
    std::cout << "Raise 5: " << t.target() << '\n';
    t.raise(8);
    std::cout << "Raise 8: " << t.target() << '\n';
    t.lower(12);
    std::cout << "Lower 12: " << t.target() << '\n';
    t.lower(15);
    std::cout << "Lower 15: " << t.target() << '\n';
    return 0;
}
